"""Re-generate docs/DATASET_AUDIT_REPORT.md (tables) and results/metrics/dataset_quality.json from the raw files."""
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))
import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402

from bms.data.loader import dataset_ids, load_dataset  # noqa: E402
from bms.preprocessing.cleaning import clean, quality_report  # noqa: E402
from bms.preprocessing.segmentation import segment_table  # noqa: E402
from bms.preprocessing.pipeline import prepare_condition  # noqa: E402
from bms.features.soc_reference import cumulative_ah  # noqa: E402
from bms.utils.config import load_dataset_config, repo_root  # noqa: E402

R = repo_root(); cfg = load_dataset_config(); Q = {}; seg_tabs = {}; extra = {}
for d in dataset_ids(cfg):
    raw = load_dataset(d, cfg=cfg); Q[d] = quality_report(raw)
    c = clean(raw); seg = segment_table(c, cfg["segmentation"]["rest_current_threshold_a"], cfg["segmentation"]["min_segment_duration_s"])
    rows = []
    for _, s in seg.iterrows():
        x = c.iloc[int(s.i0): int(s.i1) + 1]
        q = cumulative_ah(x.time_s.to_numpy(), x.current_a.to_numpy())[-1]
        rows.append({"segment": s.state_name, "duration_h": round(s.duration_s / 3600, 2), "mean_I_A": round(x.current_a.mean(), 4),
                     "V_start": round(x.voltage_v.iloc[0], 3), "V_end": round(x.voltage_v.iloc[-1], 3), "charge_Ah(signed)": round(q, 4)})
    seg_tabs[d] = pd.DataFrame(rows)
(R / "results" / "metrics").mkdir(parents=True, exist_ok=True)
json.dump(Q, open(R / "results" / "metrics" / "dataset_quality.json", "w", encoding="utf-8"), indent=2)

def md(df): return "| " + " | ".join(df.columns) + " |\n|" + "---|" * len(df.columns) + "\n" + "\n".join("| " + " | ".join(str(v) for v in r) + " |" for r in df.to_numpy())

out = ["# Dataset audit report (CALCE SP20-1, four files)", "",
       "*Generated by `scripts/generate_audit_report.py`; raw files are never modified. No previous audit existed in the workspace, so this is the first one.*", "",
       "## 1. Files and schemas", "",
       "| dataset id | file | format note | sheets used | time col. | V col. (unit) | I col. (unit) | step / cycle cols | temperature col. |", "|---|---|---|---|---|---|---|---|---|"]
for e in cfg["datasets"]:
    c = e["columns"]
    note = "OOXML zip with legacy `.xls` extension (detected by magic bytes)" if e["file"].endswith(".xls") else "xlsx"
    out.append(f"| {e['id']} | {e['file']} | {note} | {', '.join(e['sheets'])} | {c['time_s']} | {c['voltage_v']} (×{e['scale']['voltage_v']} → V) | {c['current_a']} (×{e['scale']['current_a']} → A) | {c.get('step','—')} / {c.get('cycle','—')} | {c.get('temperature_c','—')} |")
out += ["", "Only the files that contain the full Arbin schema (0 °C and 1 A files) carry `Cycle_Index`, `Step_Index`, energy and `Internal Resistance` columns; the 25 °C and 45 °C files are reduced exports (time, mV, mA, program step / nothing). The preliminary column list in the project brief therefore does **not** hold for every file.", "",
        "## 2. Data-quality metrics", "",
        md(pd.DataFrame([{"dataset": d, "rows": q["n_rows"], "duration_h": round(q["duration_h"], 2), "dup. timestamps": q["duplicated_timestamps"], "median dt (s)": round(q["dt_median_s"], 2), "max dt (s)": q["dt_max_s"], "gaps>5 s": q["n_gaps_gt_5s"], "V range": [round(x, 3) for x in q["voltage_min_max"]], "I range (A)": [round(x, 3) for x in q["current_min_max"]], "cycle idx": q["cycle_index_unique"] or "none", "missing T": q["missing_per_column"]["temperature_c"]} for d, q in Q.items()])), "",
        "Cleaning actions (`bms.preprocessing.cleaning.clean`): duplicated timestamps removed (keep first); the 0 °C workbook has one `Data_Point` repeated across its two sheets (removed at load). No out-of-range voltage/current was found.", "",
        "## 3. Protocol structure (segments found from the current sign, tolerance 20 mA, min. 10 min)", ""]
for d, t in seg_tabs.items():
    out += [f"**{d}**", "", md(t), ""]
out += ["## 4. Findings that constrain the project", "",
        "1. **One cycle only.** `Cycle_Index` is 1 in every file that has it; each file holds a single charge–rest–discharge–rest–charge sequence. There is **no ageing data** → SOH-vs-cycle and RUL cannot be built.",
        "2. **Single cell, no cell-level data** → no imbalance diagnosis, no cross-cell generalisation.",
        "3. **No temperature channel** except one single reading (23.0 °C) in the file labelled 25 °C. Temperatures 0/25/45 °C come from file names only (**unverified labels**); the 1 A file has no temperature information at all.",
        "4. **Nominal capacity is not documented** in the files. It is not assumed; SOH(%) is disabled. Delivered capacities (to the 2.5 V cut-off): see `results/metrics/soh_capacity_table.csv`.",
        "5. **No independently measured SOC.** The SOC reference is calculated by coulomb integration (see `docs/METHODOLOGY.md`).",
        "6. The 0.1 A tests start the discharge at 4.16–4.18 V after a 2 h rest (not at a CV-terminated 4.2 V), and the 25 °C / 45 °C charge phases stop near 4.15 V (incomplete charge). Therefore the SOC reference is defined on the **discharge** only.",
        "7. Delivered capacity at 45 °C (2.022 Ah) is lower than at 25 °C (2.157 Ah), which is not the usual temperature trend at equal low rate. The tests were recorded months apart (Oct 2015 – Feb 2016) on a cell with unknown history, so temperature, rate and history effects are confounded; this is reported, not explained away.",
        "8. Event-driven logging: 0 °C and 1 A files log on voltage change (gaps up to 10 s, mostly during rest); 25/45 °C files log every 1 s (integer ms/mA resolution, one 5–7 s gap at 25 °C). All signals are linearly resampled to a uniform 20 s grid for modelling.", ""]
(R / "docs" / "DATASET_AUDIT_REPORT.md").write_text("\n".join(out), encoding="utf-8")
print("written", len("\n".join(out)), "chars")
